//! Retained provider/module lifetime is acquired only after exact source replay.
use super::*;
pub(super) fn emit_entry(output: &mut impl COutput, symbol: &str) -> Result<(), Diagnostic> {
    output.push_str(include_str!("escaped.c"));
    write!(output, "\nstatic __attribute__((unused)) spx_status_token spx_checked_string_result_invoke_v1(struct spx_checked_string_result_lease_v1 *lease, struct spx_checked_string_result_handle_v1 *out) {{\n    if (!spx_checked_string_result_valid_v1(lease) || lease->busy || lease->invoked || out == NULL || lease->context->checked_allocation != NULL || lease->context->status_arena.length != UINT32_C(0)) spx_runtime_invariant_failure(\"checked String result invocation binding\");\n    struct spx_checked_string_adapter_v1 adapter = {{0}};\n    if (!spx_checked_string_adapter_init_v1(&adapter, lease->context, lease->retained, lease->allocate, lease->release)) spx_runtime_invariant_failure(\"checked String result allocator binding\");\n    lease->invoked = true; lease->busy = true;\n    lease->context->checked_allocation = &adapter;\n    char *candidate = NULL;\n    spx_status_token selected = {symbol}(lease->context, &candidate);\n    lease->context->checked_allocation = NULL; lease->busy = false; lease->selected = selected;\n    if (selected != SPX_STATUS_SUCCESS) {{\n        if (candidate != NULL) spx_runtime_invariant_failure(\"failed String result was published\");\n        return selected;\n    }}\n    struct spx_string_v10 *header = spx_string_header_v10(candidate);\n    if (header->release_state != lease->retained || header->release != lease->release) spx_runtime_invariant_failure(\"String result has foreign release provenance\");\n    lease->text = candidate;\n    *out = (struct spx_checked_string_result_handle_v1){{lease, lease->generation}};\n    return SPX_STATUS_SUCCESS;\n}}\n").expect("String output");
    Ok(())
}
